const j = $json;
const bin = $input.item.binary || {};
const key = Object.keys(bin)[0];
if (!key) throw new Error('Upload one template screenshot. It is the style reference only.');

const runMode = parseInt(String(j['Run Mode'] || '1').trim().charAt(0), 10) || 1;

let picked = j['Devices'];
if (typeof picked === 'string') picked = picked.split(',').map(s => s.trim()).filter(Boolean);
if (!Array.isArray(picked)) picked = [];

let devices = picked.map(label => {
  const m = String(label).match(/(\d{3,5})\s*x\s*(\d{3,5})/i);
  if (!m) return null;
  return {
    label,
    key: String(label).replace(/\(.*\)/, '').trim().replace(/[^A-Za-z0-9.]+/g, '-'),
    kind: /ipad/i.test(label) ? 'iPad' : 'iPhone',
    w: parseInt(m[1], 10),
    h: parseInt(m[2], 10),
  };
}).filter(Boolean);

if (devices.length === 0) {
  devices = [
    { label: 'iPhone 6.9in (1320x2868)', key: 'iPhone-6.9in', kind: 'iPhone', w: 1320, h: 2868 },
    { label: 'iPad 13in (2064x2752)', key: 'iPad-13in', kind: 'iPad', w: 2064, h: 2752 },
  ];
}

const screens = [];
for (let i = 1; i <= 6; i++) {
  const title = String(j['Screen ' + i + ' Title'] || '').trim();
  const subtitle = String(j['Screen ' + i + ' Subtitle'] || '').trim();
  const frame = String(j['Screen ' + i + ' Frame Text'] || '').trim();
  if (!title && !subtitle && !frame) continue;
  if (!title) throw new Error('Screen ' + i + ' needs a title.');
  if (!frame) throw new Error('Screen ' + i + ' needs the version text that goes inside the frame.');
  screens.push({ index: screens.length + 1, title, subtitle, frame });
}
if (screens.length === 0) {
  throw new Error('Fill Screen 1 Title, Subtitle, and Frame Text. The template image is only the style reference.');
}

const appName = String(j['App Name'] || 'App').trim() || 'App';
const drop = new Set([
  'Template Image', 'App Name', 'Run Mode', 'Devices', 'Extra Notes',
  'Group Image', 'Panel Count', 'Screens',
]);
for (let i = 1; i <= 6; i++) {
  drop.add('Screen ' + i + ' Title');
  drop.add('Screen ' + i + ' Subtitle');
  drop.add('Screen ' + i + ' Frame Text');
}
const rest = {};
Object.keys(j).forEach(k => { if (!drop.has(k)) rest[k] = j[k]; });

return {
  json: Object.assign({}, rest, {
    appName,
    runMode,
    devices,
    screens,
    notes: String(j['Extra Notes'] || '').trim(),
  }),
  binary: { data: bin[key] },
};

const cfg = $('Read Form').first().json;
const img = items[0];
if (!img.binary || !img.binary.data) throw new Error('Template image was lost before planning screens.');

const screens = cfg.screens || [];
if (!screens.length) throw new Error('No screens to generate. Fill the screen fields on the form.');

const devices = cfg.runMode >= 3 ? cfg.devices : cfg.devices.slice(0, 1);
const r16 = v => Math.max(16, Math.round(v * (cfg.gen_scale || 1) / 16) * 16);
const out = [];

screens.forEach(screen => {
  devices.forEach(d => {
    out.push({
      json: Object.assign({}, cfg, {
        devices: undefined,
        screens: undefined,
        device: d,
        genW: r16(d.w),
        genH: r16(d.h),
        panelIndex: screen.index,
        screen,
      }),
      binary: { source: img.binary.data },
      pairedItem: { item: 0 },
    });
  });
});

return out;

const j = $json;
const d = j.device;
const s = j.screen || { title: '', subtitle: '', frame: '' };
const attempt = j.attempt || 1;
const src = $input.item.binary.source;
const mime = String(src.mimeType || '');
let ext = 'png';
if (/jpe?g/i.test(mime) || /jpe?g/i.test(src.fileName || '')) ext = 'jpg';
else if (/webp/i.test(mime) || /webp/i.test(src.fileName || '')) ext = 'webp';
src.fileName = 'template_reference.' + ext;
src.fileExtension = ext;
if (ext === 'jpg') src.mimeType = 'image/jpeg';
else if (ext === 'webp') src.mimeType = 'image/webp';
else src.mimeType = 'image/png';

const deviceLine = d.kind === 'iPad'
  ? 'Show the device as a modern iPad with thin even bezels and no dynamic island. Adapt the same layout to the wider tablet canvas.'
  : 'Show the device as a modern iPhone with a dynamic island, in the same device style as the template.';

const badgeLine = j.strip_number_badge
  ? 'Do not include a numbered circle badge.'
  : 'If the template has a numbered circle badge, keep one in the same place and number it ' + j.panelIndex + '.';

const lines = [
  'You are designing ONE App Store screenshot from a style template.',
  'The attached image is a STYLE reference only. Match its layout, colours, background, typography, device mockup, icons, and spacing.',
  'Replace the words. Do not keep the template headline, subtitle, or the old text inside the device, unless those exact words are in the new copy below.',
  'Do not restyle the artwork, do not add decorations, and do not invent extra marketing lines.',
  '',
  'NEW COPY. Spell every word exactly and keep the frame line breaks:',
  'Headline: ' + (s.title || ''),
  'Subtitle: ' + (s.subtitle ? s.subtitle : '(none - do not add a subtitle)'),
  'Version text inside the device frame:',
  s.frame || '',
  '',
  'Output canvas: ' + j.genW + 'x' + j.genH + ' pixels. This is an App Store ' + d.kind + ' screenshot. Reflow the same style so it fills this canvas.',
  'Keep this vertical order: headline, subtitle, device mockup, then any caption that is part of the style.',
  'Make every word crisp, fully legible, and not cut off. Keep comfortable margins.',
  deviceLine,
  badgeLine,
];

if (j.appName) lines.push('The app is called "' + j.appName + '". Keep that name wherever the template shows the product name.');
if (j.notes) lines.push('Extra notes from the user: ' + j.notes);
if (attempt > 1 && j.feedback) lines.push('IMPORTANT. Fix these problems from the previous attempt: ' + j.feedback);

return {
  json: Object.assign({}, j, { attempt, prompt: lines.join('\n') }),
  binary: { source: src },
};

const prev = $('Build Prompt').first();
const res = $json;
const b64 = res && res.data && res.data[0] && res.data[0].b64_json;
if (!b64) throw new Error('OpenAI returned no image: ' + JSON.stringify(res).slice(0, 600));

const idx = String(prev.json.panelIndex).padStart(2, '0');
const bin = await this.helpers.prepareBinaryData(
  Buffer.from(b64, 'base64'),
  'panel_' + idx + '_' + prev.json.device.key + '_try' + prev.json.attempt + '.png',
  'image/png'
);
return { json: prev.json, binary: { source: prev.binary.source, data: bin } };

const j = $json;
const s = j.screen || { title: '', subtitle: '', frame: '' };

function mediaType(bin) {
  const m = String((bin && bin.mimeType) || '').toLowerCase();
  const n = String((bin && bin.fileName) || '').toLowerCase();
  if (m.includes('png') || n.endsWith('.png')) return 'image/png';
  if (m.includes('webp') || n.endsWith('.webp')) return 'image/webp';
  if (m.includes('gif') || n.endsWith('.gif')) return 'image/gif';
  if (m.includes('jpeg') || m.includes('jpg') || n.endsWith('.jpg') || n.endsWith('.jpeg')) return 'image/jpeg';
  return 'image/png';
}

const srcBin = $input.item.binary.source;
const genBin = $input.item.binary.data;
const srcBuf = await this.helpers.getBinaryDataBuffer($itemIndex, 'source');
const genBuf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');

const subtitleRule = s.subtitle
  ? 'Expected subtitle: ' + s.subtitle
  : 'Expected subtitle: none. The redraw must not add a subtitle.';

const rubric = [
  'IMAGE 1 is a STYLE TEMPLATE. Its old headline, subtitle, and in-frame text are supposed to be replaced.',
  'IMAGE 2 is the new App Store screenshot. Judge the new copy and whether the style still matches the template.',
  'Expected headline: ' + (s.title || ''),
  subtitleRule,
  'Expected version text inside the device:',
  s.frame || '',
  'Check, in this order:',
  '1. TEXT: headline, subtitle, and the version text inside the device match the expected copy word for word. List wrong, missing, garbled, invented, or leftover template text.',
  '2. STYLE: same layout structure, colours, background, device mockup, and typography as the template. No new decorative elements.',
  '3. FRAME: the version text is inside the device, readable, and not cut off.',
  '4. TECHNICAL: nothing important is cut off at the canvas edge, and there are no obvious image artefacts.',
  'The output aspect ratio may differ from the template. Ignore exact proportions.',
  'Reply with ONLY one JSON object, no markdown, in this shape:',
  '{"verdict":"PASS" or "FAIL","score":0-10,"text_errors":["..."],"issues":["..."],"fix_instructions":"one short paragraph telling the image model exactly what to fix, or empty if PASS"}',
  'Use PASS only if score >= 8 and text_errors is empty.',
].join('\n');

const body = {
  model: j.claude_model,
  max_tokens: 1200,
  system: 'You are a strict QA reviewer for App Store screenshot artwork. You check that a new screenshot keeps the template style and uses the requested title, subtitle, and in-frame version text. You never rewrite the design.',
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: 'IMAGE 1 = STYLE TEMPLATE (old words should not be copied):' },
      { type: 'image', source: { type: 'base64', media_type: mediaType(srcBin), data: srcBuf.toString('base64') } },
      { type: 'text', text: 'IMAGE 2 = NEW SCREENSHOT:' },
      { type: 'image', source: { type: 'base64', media_type: mediaType(genBin), data: genBuf.toString('base64') } },
      { type: 'text', text: rubric },
    ],
  }],
};

return { json: Object.assign({}, j, { claudeBody: body }), binary: $input.item.binary };

const prev = $('Build Claude Request').first();
const base = Object.assign({}, prev.json);
delete base.claudeBody;

const text = (($json.content || []).filter(c => c.type === 'text').map(c => c.text)).join('\n');
let review = null;
try {
  const m = text.match(/\{[\s\S]*\}/);
  review = JSON.parse(m[0]);
} catch (e) {
  review = null;
}

const attempt = base.attempt || 1;
const max = base.max_attempts || 2;
const s = base.screen || { title: '', subtitle: '', frame: '' };

let verdict = 'UNREVIEWED';
let score = null;
let issues = [];
let feedback = '';
if (review) {
  verdict = String(review.verdict || '').toUpperCase() === 'PASS' ? 'PASS' : 'FAIL';
  score = typeof review.score === 'number' ? review.score : null;
  issues = [].concat(review.text_errors || [], review.issues || []);
  const expected = [
    'Headline must read exactly: "' + s.title + '".',
    s.subtitle ? 'Subtitle must read exactly: "' + s.subtitle + '".' : 'Do not add a subtitle.',
    'Version text inside the frame must read exactly: "' + s.frame + '".',
  ].join(' ');
  const textFix = (review.text_errors || []).length ? 'Text fixes: ' + review.text_errors.join('; ') : '';
  feedback = [expected, review.fix_instructions || '', textFix].join(' ').trim();
}

const needsRetry = verdict === 'FAIL' && attempt < max;

return {
  json: Object.assign({}, base, {
    reviewVerdict: verdict,
    reviewScore: score,
    reviewIssues: issues,
    needsRetry,
    attemptsUsed: attempt,
    attempt: needsRetry ? attempt + 1 : attempt,
    feedback: needsRetry ? feedback : '',
    reviewRaw: review ? undefined : text.slice(0, 400),
  }),
  binary: prev.binary,
};

const incomingJson = ($json && $json.device) ? $json : $('Export Sizes?').first().json;
const j = incomingJson;
const idx = String(j.panelIndex).padStart(2, '0');
const app = String(j.appName || 'App').replace(/[^A-Za-z0-9]+/g, '') || 'App';
const titleSlug = String((j.screen && j.screen.title) || 'screen').replace(/[^A-Za-z0-9]+/g, '').slice(0, 28) || 'screen';
const ext = (String(j.export_format || 'jpeg').toLowerCase() === 'png' ? 'png' : 'jpg');
const mime = ext === 'png' ? 'image/png' : 'image/jpeg';
const name = app + '_' + j.device.key + '_panel' + idx + '_' + titleSlug + '.' + ext;
const incoming = $input.item.binary || {};
const binKey = incoming.data ? 'data' : Object.keys(incoming)[0];
if (!binKey) throw new Error('No image was returned for ' + name);
const bin = Object.assign({}, incoming[binKey], { fileName: name, fileExtension: ext, mimeType: mime });
return {
  json: {
    appName: j.appName,
    panel: j.panelIndex,
    title: j.screen ? j.screen.title : '',
    subtitle: j.screen ? j.screen.subtitle : '',
    frame: j.screen ? j.screen.frame : '',
    device: j.device.label,
    file: name,
    verdict: j.reviewVerdict || 'not reviewed (mode 1)',
    score: j.reviewScore == null ? null : j.reviewScore,
    attemptsUsed: j.attemptsUsed || j.attempt || 1,
    issues: j.reviewIssues || [],
    reviewRaw: j.reviewRaw || null,
  },
  binary: { data: bin },
};

const incomingJson = ($json && $json.device) ? $json : $('Export Sizes?').first().json;
const j = incomingJson;
const idx = String(j.panelIndex).padStart(2, '0');
const app = String(j.appName || 'App').replace(/[^A-Za-z0-9]+/g, '') || 'App';
const titleSlug = String((j.screen && j.screen.title) || 'screen').replace(/[^A-Za-z0-9]+/g, '').slice(0, 28) || 'screen';
const ext = 'png';
const mime = ext === 'png' ? 'image/png' : 'image/jpeg';
const name = app + '_' + j.device.key + '_panel' + idx + '_' + titleSlug + '_draft.' + ext;
const incoming = $input.item.binary || {};
const binKey = incoming.data ? 'data' : Object.keys(incoming)[0];
if (!binKey) throw new Error('No image was returned for ' + name);
const bin = Object.assign({}, incoming[binKey], { fileName: name, fileExtension: ext, mimeType: mime });
return {
  json: {
    appName: j.appName,
    panel: j.panelIndex,
    title: j.screen ? j.screen.title : '',
    subtitle: j.screen ? j.screen.subtitle : '',
    frame: j.screen ? j.screen.frame : '',
    device: j.device.label,
    file: name,
    verdict: j.reviewVerdict || 'not reviewed (mode 1)',
    score: j.reviewScore == null ? null : j.reviewScore,
    attemptsUsed: j.attemptsUsed || j.attempt || 1,
    issues: j.reviewIssues || [],
    reviewRaw: j.reviewRaw || null,
  },
  binary: { data: bin },
};

if (items.length === 0) throw new Error('Nothing was generated.');
const binary = {};
const keys = [];
const report = [];
items.forEach((it, i) => {
  const k = 'f' + i;
  binary[k] = it.binary.data;
  keys.push(k);
  report.push(it.json);
});
const reportBin = await this.helpers.prepareBinaryData(
  Buffer.from(JSON.stringify({ files: report }, null, 2)),
  'report.json',
  'application/json'
);
binary.report = reportBin;
keys.push('report');
const app = String(items[0].json.appName || 'App').replace(/[^A-Za-z0-9]+/g, '') || 'App';
return [{
  json: {
    fileKeys: keys.join(','),
    zipName: app + '_screenshots.zip',
    fileCount: items.length,
    report,
  },
  binary,
}];
